PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'customer',active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS reset_tokens(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),name TEXT NOT NULL,description TEXT NOT NULL,brand TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),selling_unit TEXT NOT NULL,attributes TEXT NOT NULL DEFAULT '{}',image TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ARCHIVED' CHECK(status IN ('ACTIVE','ARCHIVED')),stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),origin TEXT,material TEXT,average_rating REAL NOT NULL DEFAULT 0 CHECK(average_rating BETWEEN 0 AND 5),product_type TEXT CHECK(product_type IN ('pen','notebook','bag','toy','book','electric_device')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')));
CREATE TABLE IF NOT EXISTS carts(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),owner TEXT NOT NULL UNIQUE,customer_id TEXT UNIQUE REFERENCES users(id),status TEXT NOT NULL DEFAULT 'EMPTY' CHECK(status IN ('EMPTY','HAS_ITEMS')),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')));
CREATE TABLE IF NOT EXISTS cart_items(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),cart_id TEXT NOT NULL REFERENCES carts(id),product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')),UNIQUE(cart_id,product_id));
CREATE TABLE IF NOT EXISTS promotions(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),code TEXT UNIQUE NOT NULL,percent INTEGER CHECK(percent BETWEEN 1 AND 50),minimum INTEGER CHECK(minimum>=0),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),user_id TEXT NOT NULL REFERENCES users(id),idem_key TEXT NOT NULL,request_hash TEXT NOT NULL,recipient TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,subtotal INTEGER NOT NULL,discount INTEGER NOT NULL,shipping INTEGER NOT NULL,total INTEGER NOT NULL,promo TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,UNIQUE(user_id,idem_key));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,selling_unit TEXT NOT NULL,snapshot_details TEXT NOT NULL DEFAULT '{}',quantity INTEGER NOT NULL CHECK(quantity>0),price INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),method TEXT NOT NULL CHECK(method IN ('COD','ONLINE')),status TEXT NOT NULL CHECK(status IN ('PENDING','PROCESSING','PAID','FAILED','REFUNDED')),reference TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),idempotency_key TEXT NOT NULL UNIQUE,failure_reason TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')));
CREATE TABLE IF NOT EXISTS payment_events(event_id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),result TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_movements(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),product_id TEXT REFERENCES products(id),order_id TEXT REFERENCES orders(id),quantity INTEGER NOT NULL,kind TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_history(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),order_id TEXT REFERENCES orders(id),status TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),user_id TEXT REFERENCES users(id),message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),user_id TEXT NOT NULL REFERENCES users(id),product_id TEXT NOT NULL REFERENCES products(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS shipments(order_id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) REFERENCES orders(id),provider TEXT NOT NULL,tracking_code TEXT UNIQUE NOT NULL,status TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tracking_events(event_id TEXT PRIMARY KEY,order_id TEXT REFERENCES orders(id),status TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS service_cases(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),user_id TEXT REFERENCES users(id),order_id TEXT REFERENCES orders(id),product_id TEXT REFERENCES products(id),subject TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',reply TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS replenishments(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),supplier TEXT NOT NULL,product_id TEXT REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),status TEXT NOT NULL DEFAULT 'requested',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),actor TEXT NOT NULL,action TEXT NOT NULL,record TEXT NOT NULL,created_at TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS auth_sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_reservations(order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS product_image(id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(id)=36),product_id TEXT NOT NULL REFERENCES products(id),image_url TEXT NOT NULL,is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)),encoder_version TEXT,vector_reference TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')),UNIQUE(product_id,image_url));
CREATE UNIQUE INDEX IF NOT EXISTS one_primary_product_image ON product_image(product_id) WHERE is_primary=1;
CREATE TABLE IF NOT EXISTS pen(product_id TEXT PRIMARY KEY NOT NULL REFERENCES products(id),color TEXT,type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notebook(product_id TEXT PRIMARY KEY NOT NULL REFERENCES products(id),page_num INTEGER NOT NULL CHECK(page_num>0),size TEXT NOT NULL,type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bag(product_id TEXT PRIMARY KEY NOT NULL REFERENCES products(id),size TEXT NOT NULL,pattern TEXT);
CREATE TABLE IF NOT EXISTS toy(product_id TEXT PRIMARY KEY NOT NULL REFERENCES products(id),type TEXT NOT NULL,minimum_age INTEGER CHECK(minimum_age>=0));
CREATE TABLE IF NOT EXISTS book(product_id TEXT PRIMARY KEY NOT NULL REFERENCES products(id),category TEXT NOT NULL,minimum_age INTEGER CHECK(minimum_age>=0),publisher TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS electric_device(product_id TEXT PRIMARY KEY NOT NULL REFERENCES products(id),minimum_age INTEGER CHECK(minimum_age>=0),weight INTEGER CHECK(weight>=0));
CREATE TABLE IF NOT EXISTS search_query(query_id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(query_id)=36),customer_id TEXT REFERENCES users(id),guest_owner TEXT,modality TEXT NOT NULL CHECK(modality IN ('TEXT','VOICE','IMAGE','MULTIMODAL')),raw_text TEXT,normalized_text TEXT,language TEXT,encoder_version TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')));
CREATE TABLE IF NOT EXISTS search_filter(filter_id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(filter_id)=36),query_id TEXT NOT NULL REFERENCES search_query(query_id) ON DELETE CASCADE,filter_type TEXT NOT NULL CHECK(filter_type IN ('CATEGORY','BRAND','MIN_PRICE','MAX_PRICE','AVAILABLE','COLOR','SIZE','MINIMUM_AGE','PUBLISHER')),filter_value TEXT NOT NULL,is_explicit INTEGER NOT NULL DEFAULT 1,is_hard INTEGER NOT NULL DEFAULT 1,was_relaxed INTEGER NOT NULL DEFAULT 0,relaxation_order INTEGER,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')));
CREATE TABLE IF NOT EXISTS search_result(result_id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(result_id)=36),query_id TEXT NOT NULL REFERENCES search_query(query_id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),rank_position INTEGER NOT NULL CHECK(rank_position>0),relevance_score REAL NOT NULL DEFAULT 0,preference_score REAL NOT NULL DEFAULT 0,final_score REAL NOT NULL DEFAULT 0,explanation TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')),UNIQUE(query_id,rank_position));
CREATE TABLE IF NOT EXISTS query_media(media_id TEXT PRIMARY KEY NOT NULL DEFAULT (uuid()) CHECK(length(media_id)=36),query_id TEXT NOT NULL REFERENCES search_query(query_id) ON DELETE CASCADE,media_type TEXT NOT NULL CHECK(media_type IN ('IMAGE','VOICE')),storage_reference TEXT NOT NULL,mime_type TEXT,file_size_bytes INTEGER,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%S+00:00','now')),expires_at TEXT);
CREATE TRIGGER IF NOT EXISTS cart_added AFTER INSERT ON cart_items BEGIN UPDATE carts SET status='HAS_ITEMS',updated_at=strftime('%Y-%m-%dT%H:%M:%S+00:00','now') WHERE id=NEW.cart_id; END;
CREATE TRIGGER IF NOT EXISTS cart_removed AFTER DELETE ON cart_items BEGIN UPDATE carts SET status=CASE WHEN EXISTS(SELECT 1 FROM cart_items WHERE cart_id=OLD.cart_id) THEN 'HAS_ITEMS' ELSE 'EMPTY' END,updated_at=strftime('%Y-%m-%dT%H:%M:%S+00:00','now') WHERE id=OLD.cart_id; END;
CREATE TRIGGER IF NOT EXISTS cart_changed AFTER UPDATE ON cart_items BEGIN UPDATE carts SET updated_at=strftime('%Y-%m-%dT%H:%M:%S+00:00','now') WHERE id=NEW.cart_id; END;
CREATE TRIGGER IF NOT EXISTS stock_guard BEFORE UPDATE OF stock ON products WHEN NEW.stock < COALESCE((SELECT SUM(quantity) FROM inventory_reservations WHERE product_id=NEW.id),0) BEGIN SELECT RAISE(ABORT,'Stock below reserved quantity'); END;
CREATE TRIGGER IF NOT EXISTS reservation_guard BEFORE INSERT ON inventory_reservations WHEN NEW.quantity+COALESCE((SELECT SUM(quantity) FROM inventory_reservations WHERE product_id=NEW.product_id),0) > (SELECT stock FROM products WHERE id=NEW.product_id) BEGIN SELECT RAISE(ABORT,'Insufficient available stock'); END;
CREATE TRIGGER IF NOT EXISTS pen_type_guard BEFORE INSERT ON pen WHEN (SELECT product_type FROM products WHERE id=NEW.product_id) IS NOT 'pen' BEGIN SELECT RAISE(ABORT,'Product subtype mismatch'); END;
CREATE TRIGGER IF NOT EXISTS notebook_type_guard BEFORE INSERT ON notebook WHEN (SELECT product_type FROM products WHERE id=NEW.product_id) IS NOT 'notebook' BEGIN SELECT RAISE(ABORT,'Product subtype mismatch'); END;
CREATE TRIGGER IF NOT EXISTS bag_type_guard BEFORE INSERT ON bag WHEN (SELECT product_type FROM products WHERE id=NEW.product_id) IS NOT 'bag' BEGIN SELECT RAISE(ABORT,'Product subtype mismatch'); END;
CREATE TRIGGER IF NOT EXISTS toy_type_guard BEFORE INSERT ON toy WHEN (SELECT product_type FROM products WHERE id=NEW.product_id) IS NOT 'toy' BEGIN SELECT RAISE(ABORT,'Product subtype mismatch'); END;
CREATE TRIGGER IF NOT EXISTS book_type_guard BEFORE INSERT ON book WHEN (SELECT product_type FROM products WHERE id=NEW.product_id) IS NOT 'book' BEGIN SELECT RAISE(ABORT,'Product subtype mismatch'); END;
CREATE TRIGGER IF NOT EXISTS electric_device_type_guard BEFORE INSERT ON electric_device WHEN (SELECT product_type FROM products WHERE id=NEW.product_id) IS NOT 'electric_device' BEGIN SELECT RAISE(ABORT,'Product subtype mismatch'); END;
PRAGMA user_version=3;

CREATE INDEX IF NOT EXISTS reservation_product ON inventory_reservations(product_id);
CREATE INDEX IF NOT EXISTS order_customer_date ON orders(user_id,created_at);
CREATE INDEX IF NOT EXISTS search_customer_date ON search_query(customer_id,created_at);
CREATE INDEX IF NOT EXISTS search_created ON search_query(created_at);
CREATE TRIGGER IF NOT EXISTS product_updated AFTER UPDATE ON products WHEN NEW.updated_at=OLD.updated_at BEGIN UPDATE products SET updated_at=strftime('%Y-%m-%dT%H:%M:%S+00:00','now') WHERE id=NEW.id; END;

CREATE TABLE IF NOT EXISTS migration_archive(name TEXT PRIMARY KEY,data TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS active_product_type_insert BEFORE INSERT ON products WHEN NEW.status='ACTIVE' AND NEW.product_type IS NULL BEGIN SELECT RAISE(ABORT,'Active product requires a product type'); END;
CREATE TRIGGER IF NOT EXISTS active_product_type_update BEFORE UPDATE OF status,product_type ON products WHEN NEW.status='ACTIVE' AND NEW.product_type IS NULL BEGIN SELECT RAISE(ABORT,'Active product requires a product type'); END;

CREATE TABLE IF NOT EXISTS catalogue_sources(product_id TEXT PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE,source TEXT NOT NULL,source_product_id TEXT NOT NULL,source_variant_id TEXT NOT NULL,source_url TEXT NOT NULL,source_name TEXT NOT NULL,source_image_url TEXT NOT NULL,source_available INTEGER NOT NULL CHECK(source_available IN (0,1)),demo_available INTEGER NOT NULL CHECK(demo_available>0),imported_at TEXT NOT NULL,UNIQUE(source,source_variant_id));
